import{_ as e,o,c as t,a0 as i}from"./chunks/framework.DQOulFGV.js";const p=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1786677154000}'),r={name:"guide/introduction.md"};function l(n,a,s,d,c,u){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p>jayapp 是一个面向 <strong>uni-app Vue3</strong> 的跨端 UI 组件库，以运行时主题、完整类型提示与单元测试保障，提供现代、易用的多端组件体验。</p><h2 id="产品定位" tabindex="-1">产品定位 <a class="header-anchor" href="#产品定位" aria-label="Permalink to &quot;产品定位&quot;">​</a></h2><ul><li><strong>轻便</strong>：零运行时依赖，easycom 按需加载，用多少打包多少。</li><li><strong>易用</strong>：三四行完成接入；智能默认值；<code>$jay</code> 全局对象提供一行式函数 API。</li><li><strong>丰富</strong>：首期提供 10 个核心组件范本，路线图覆盖 60+ 组件。</li><li><strong>多端</strong>：H5、小程序、App 无感适配，样式与行为全端一致。</li></ul><h2 id="核心优势" tabindex="-1">核心优势 <a class="header-anchor" href="#核心优势" aria-label="Permalink to &quot;核心优势&quot;">​</a></h2><p>jayapp 在以下维度做了代际升级：</p><ol><li><strong>运行时主题系统</strong>：基于 Design Token + CSS 变量，亮/暗模式运行时即时切换，无需重新编译；支持传入自定义 Token 覆盖，轻松实现品牌换肤。</li><li><strong>Composition API + 类型提示</strong>：组件全部 <code>&lt;script setup&gt;</code> 编写，<code>useProps</code> composable 替代 mixin；JSDoc + <code>.d.ts</code> 提供完整类型提示。</li><li><strong>单元测试体系</strong>：内置 Vitest + @vue/test-utils 测试，核心逻辑与组件行为可验证、可回归。</li></ol><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h2><ul><li>组件样式统一消费 CSS 变量（<code>var(--jay-xxx, 兜底值)</code>），保证运行时主题在所有端生效。</li><li>函数式 API（<code>$jay.toast</code> / <code>$jay.modal</code>）通过全局事件总线与页面单例组件通信，任意位置一行调用。</li><li>源码即 npm 包：目录结构即发布结构，<code>npm publish</code> 直接可用。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./quick-start.html">快速上手</a></li><li><a href="./theme.html">运行时主题</a></li></ul>',11)])])}const m=e(r,[["render",l]]);export{p as __pageData,m as default};
